e:9px}.nwp-values b{margin-top:5px;color:#dffaff;font:14px ui-monospace,monospace}.matrix-head{display:flex;justify-content:space-between;margin:22px 0 10px}.matrix-head strong{font-size:14px}.matrix-head span{color:#7896a8;font-size:10px}.matrix{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.station-card{padding:15px;cursor:pointer}.station-card.selected{border-color:#39d9ff;box-shadow:0 0 18px rgba(57,217,255,.14)}.station-top{display:flex;justify-content:space-between}.station-top strong{color:#dffaff;font:15px ui-monospace,monospace}.station-top span{color:#7896a8;font-size:10px}.station-card>b{display:block;margin-top:22px;color:#3ee5b1;font:24px ui-monospace,monospace}.station-card em{font:10px sans-serif;color:#78a5b5}.station-card p,.station-card small{display:block;color:#7896a8;font-size:10px}.station-card p{margin:12px 0 6px}@media(max-width:1200px){.brand{min-width:350px}.matrix{grid-template-columns:repeat(3,1fr)}}@media(max-width:900px){header{padding:0 14px}.brand{min-width:0}.brand h1{font-size:14px}.content{padding:16px}.main-grid{grid-template-columns:1fr}.matrix{grid-template-columns:repeat(2,1fr)}.kpis{grid-template-columns:repeat(2,1fr)}}</style>









